  { id: "pe_gu_hypospadias", system: "inguinal_hernia_genitourinary_dre", subGroup: "genital_exam", en: "Hypospadias or Epispadias", fa: "هیپوسپادیاس / اپی‌سپادیاس (Hypospadias)", aliases: "جابجایی مئاتوس ادراری", isCore: false, normalState: 0, detailHint: "محل قرارگیری دهانه مجرای ادرار." },
  { id: "pe_gu_phimosis", system: "inguinal_hernia_genitourinary_dre", subGroup: "genital_exam", en: "Phimosis or Paraphimosis", fa: "فیموز یا پارافیموز (Phimosis / Paraphimosis)", aliases: "تنگی یا گیرافتادن پوست ختنه‌گاه", isCore: false, normalState: -1, detailHint: "وجود حلقه تنگ و ادم گلنس در پارافیموز." },
  { id: "pe_gu_testes_descended", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Bilaterally Descended Normal Testes", fa: "نزول دوطرفه بیضه‌ها با قوام طبیعی (Normal Descended Testes)", aliases: "کریپتورکیدیسم بیضه نزول نکرده", isCore: false, normalState: 1, detailHint: "در صورت عدم نزول (منفی)، سمت و محل لمس در کانال را ثبت کنید." },
  { id: "pe_gu_testicular_mass", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Testicular Mass or Swelling", fa: "توده یا تورم بیضه (Testicular Mass / Swelling)", aliases: "تومور بیضه تورم اسکروتوم", isCore: false, normalState: -1, detailHint: "سمت، داخل یا خارج بیضه‌ای بودن، قوام و تندرنس." },
  { id: "pe_gu_hydrocele", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Hydrocele (Positive Transillumination)", fa: "هیدروسل (Hydrocele)", aliases: "تجمع مایع اسکروتوم ترانس ایلومینیشن مثبت", isCore: false, normalState: -1, detailHint: "سمت و نتیجه تست عبور نور (Transillumination)." },
  { id: "pe_gu_varicocele", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Varicocele", fa: "واریکوسل (Varicocele)", aliases: "اتساع شبکه پامپینیفرم کیسه کرم خاکی", isCore: false, normalState: -1, detailHint: "سمت و گرید واریکوسل (I تا III) در حالت ایستاده و والسالوا." },
  { id: "pe_gu_epididymal_swelling", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Epididymal Tenderness or Swelling", fa: "تورم و تندرنس اپیدیدیم (Epididymitis Signs)", aliases: "اپیدیدیمیت ارکیت", isCore: false, normalState: -1, detailHint: "سمت و درگیری دم یا کل اپیدیدیم." },
  { id: "pe_cremasteric_reflex", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Cremasteric Reflex", fa: "رفلکس کرماستریک (Cremasteric Reflex)", aliases: "بالا رفتن بیضه با تحریک ران تورشن بیضه", isCore: false, normalState: 1, detailHint: "در حالت طبیعی (مثبت) بیضه بالا می‌رود؛ غایب بودن (منفی) در شک به تورشن بیضه مهم است." },
  { id: "pe_prehns_sign", system: "inguinal_hernia_genitourinary_dre", subGroup: "scrotum_testes", en: "Prehn's Sign", fa: "علامت پرهن (Prehn's Sign)", aliases: "کاهش درد با بالا بردن بیضه", isCore: false, normalState: -1, detailHint: "تغییر شدت درد اسکروتوم با بالا نگه داشتن بیضه." },
  { id: "pe_dre_prostate_enlarged", system: "inguinal_hernia_genitourinary_dre", subGroup: "dre", en: "Prostatomegaly / Prostatic Nodule / Boggy Prostate", fa: "بزرگی، ندول یا تندرنس پروستات (Abnormal Prostate)", aliases: "BPH پروستاتیت ندول پروستات", isCore: false, normalState: -1, detailHint: "بزرگی متقارن، محو شدن شیار میانی، ندول سفت یا تندرنس گرم (Boggy)." },
  { id: "pe_dre_anal_fissure", system: "inguinal_hernia_genitourinary_dre", subGroup: "dre", en: "Anal Fissure or Fistula", fa: "شقاق یا فیستول مقعدی (Anal Fissure / Fistula)", aliases: "فیشر آنال زخم مقعد", isCore: false, normalState: -1, detailHint: "موقعیت ساعت‌محور (خلفی یا قدامی) و وجود اسکین تگ نگهبان." },
  { id: "pe_dre_external_hemorrhoids", system: "inguinal_hernia_genitourinary_dre", subGroup: "dre", en: "Internal or External Hemorrhoids", fa: "هموروئید داخلی یا خارجی (Hemorrhoids)", aliases: "بواسیر ترومبوزه پرولاپس هموروئید", isCore: false, normalState: -1, detailHint: "داخلی یا خارجی بودن، درجه پرولاپس و وجود ترومبوز." },
  { id: "pe_dre_rectal_prolapse", system: "inguinal_hernia_genitourinary_dre", subGroup: "dre", en: "Rectal Prolapse", fa: "پرولاپس رکتوم (Rectal Prolapse)", aliases: "بیرون‌زدگی مخاط رکتوم", isCore: false, normalState: -1, detailHint: "مخاطی یا تمام‌ضخامت بودن پرولاپس." },
  { id: "pe_dre_anal_wink", system: "inguinal_hernia_genitourinary_dre", subGroup: "dre", en: "Anal Wink Reflex", fa: "رفلکس آنال وینک (Anal Wink Reflex)", aliases: "رفلکس مقعدی S2 S3 S4", isCore: false, normalState: 1, detailHint: "در حالت طبیعی (مثبت) تحریک پوست پری‌آنال موجب انقباض اسفنکتر خارجی می‌شود." },

  // ==========================================
  // 9. musculoskeletal_spine (Core: 6)
  // ==========================================
  { id: "pe_ms_gait_normal", system: "musculoskeletal_spine", subGroup: "gait_posture", en: "Normal Station and Gait", fa: "الگوی راه‌رفتن و ایستادن طبیعی (Normal Gait)", aliases: "گیت طبیعی لنگش", isCore: true, normalState: 1, detailHint: "در صورت اختلال (منفی)، نوع گیت (آنتالژیک، آتاکسیک، پارکینسونی، ترندلنبرگ) را مشخص کنید." },
  { id: "pe_ms_spine_alignment_normal", system: "musculoskeletal_spine", subGroup: "spine", en: "Normal Spinal Alignment", fa: "راستای طبیعی ستون فقرات (Normal Spinal Alignment)", aliases: "ستون فقرات صاف", isCore: true, normalState: 1, detailHint: "انحناهای فیزیولوژیک گردنی، پشتی و کمری طبیعی است." },
  { id: "pe_ms_joint_rom_full", system: "musculoskeletal_spine", subGroup: "range_of_motion", en: "Full Active & Passive Range of Motion (ROM)", fa: "دامنه حرکتی کامل مفاصل و ستون فقرات (Full ROM)", aliases: "ROM کامل یا محدودیت حرکت مفصل", isCore: true, normalState: 1, detailHint: "در صورت محدودیت (منفی)، مفصل و جهت حرکت محدودشده را ثبت کنید." },
  { id: "pe_ms_joint_swelling", system: "musculoskeletal_spine", subGroup: "joint_inspection", en: "Joint Swelling, Erythema, or Deformity", fa: "تورم، گرمی یا دفورمیتی مفصل (Joint Swelling / Deformity)", aliases: "آرتریت ورم و قرمزی مفصل", isCore: true, normalState: -1, detailHint: "مفصل درگیر، سمت و وجود گرمی، اریتم یا دفورمیتی." },
  { id: "pe_ms_joint_effusion", system: "musculoskeletal_spine", subGroup: "joint_inspection", en: "Joint Effusion", fa: "افیوژن مفصلی (Joint Effusion)", aliases: "تجمع مایع در مفصل زانو", isCore: true, normalState: -1, detailHint: "مفصل درگیر، سمت و میزان افیوژن." },
  { id: "pe_ms_paraspinal_spasm", system: "musculoskeletal_spine", subGroup: "spine", en: "Spinal / Paraspinal Tenderness or Spasm", fa: "تندرنس مهره‌ای یا اسپاسم پارااسپاینال (Spinal Tenderness / Spasm)", aliases: "حساسیت زوائد خاری گرفتگی عضلات کمر و گردن", isCore: true, normalState: -1, detailHint: "سطح مهره‌ای (گردنی، پشتی، کمری، ساکروایلیاک) و سمت." },

  { id: "pe_ms_antalgic_gait", system: "musculoskeletal_spine", subGroup: "gait_posture", en: "Antalgic or Ataxic Gait", fa: "گیت آنتالژیک یا آتاکسیک (Abnormal Gait)", aliases: "لنگش دردناک راه رفتن ناپایدار", isCore: false, normalState: -1, detailHint: "نوع اختلال گیت و سمت درگیر." },
  { id: "pe_ms_scoliosis", system: "musculoskeletal_spine", subGroup: "spine", en: "Scoliosis, Kyphosis, or Hyperlordosis", fa: "اسکولیوز، کیفوز یا هایپرلوردوز (Spinal Deformity)", aliases: "انحراف ستون فقرات قوز گودی کمر", isCore: false, normalState: -1, detailHint: "نوع انحراف و سطح ستون فقرات." },
  { id: "pe_ms_step_off", system: "musculoskeletal_spine", subGroup: "spine", en: "Spinal Step-Off Deformity", fa: "دفورمیتی پله‌ای زوائد خاری (Spinal Step-Off)", aliases: "استپ‌آف مهره‌ای اسپوندیلولیستزیس", isCore: false, normalState: -1, detailHint: "سطح مهره‌ای دارای ناپیوستگی در لمس خط وسط." },
  { id: "pe_ms_joint_crepitus", system: "musculoskeletal_spine", subGroup: "joint_inspection", en: "Joint Crepitus", fa: "کریپتوس مفصلی (Joint Crepitus)", aliases: "صدای ساییدگی مفصل آرتروز", isCore: false, normalState: -1, detailHint: "مفصل و سمت دارای کریپتوس حین حرکت." },
  { id: "pe_slr", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Straight Leg Raise (SLR) Test", fa: "تست بالا آوردن پای صاف (SLR / Lasègue Test)", aliases: "تست لازگ سیاتیک رادیکولوپاتی کمری", isCore: false, normalState: -1, detailHint: "در صورت مثبت بودن، زاویه بروز درد رادیکولار تیرکشنده (۳۰ تا ۷۰ درجه) و سمت را ثبت کنید." },
  { id: "pe_lachman", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Lachman Test", fa: "تست لاکمن (Lachman Test)", aliases: "پارگی رباط صلیبی قدامی ACL", isCore: false, normalState: -1, detailHint: "میزان جابجایی قدامی تیبیا و کیفیت نقطه پایانی (Endpoint) در مقایسه با سمت مقابل." },
  { id: "pe_mcmurray", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "McMurray Test", fa: "تست مک‌موری (McMurray Test)", aliases: "پارگی منیسک داخلی یا خارجی زانو", isCore: false, normalState: -1, detailHint: "بروز کلیک دردناک یا قفل شدن در خط مفصلی داخلی یا خارجی زانو." },
  { id: "pe_anterior_drawer", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Anterior Drawer Test", fa: "تست کشوی قدامی (Anterior Drawer Test)", aliases: "کشوی قدامی زانو یا مچ پا ACL", isCore: false, normalState: -1, detailHint: "جابجایی قدامی بیش از حد تیبیا در فلکسیون ۹۰ درجه زانو." },
  { id: "pe_posterior_drawer", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Posterior Drawer Test", fa: "تست کشوی خلفی (Posterior Drawer Test)", aliases: "پارگی رباط صلیبی خلفی PCL", isCore: false, normalState: -1, detailHint: "جابجایی خلفی غیرطبیعی تیبیا." },
  { id: "pe_phalen", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Phalen Test", fa: "تست فالن (Phalen Test)", aliases: "سندرم تونل کارپال عصب مدین CTS", isCore: false, normalState: -1, detailHint: "بروز گزگز و پارستزی در قلمرو عصب مدین با فلکسیون مچ دست به مدت ۶۰ ثانیه." },
  { id: "pe_tinel", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Tinel Sign", fa: "علامت تینل (Tinel Sign)", aliases: "ضربه روی عصب مدین در مچ دست تونل کارپال", isCore: false, normalState: -1, detailHint: "انتشار حس برق‌گرفتگی یا پارستزی با دق روی مسیر عصب." },
  { id: "pe_finkelstein", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Finkelstein Test", fa: "تست فینکلشتاین (Finkelstein Test)", aliases: "تنوسینوویت دکرون شست دست", isCore: false, normalState: -1, detailHint: "بروز درد تیز روی زائده استیلوئید رادیوس با انحراف اولنار مچ دست." },
  { id: "pe_spurling", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Spurling Test", fa: "تست اسپارلینگ (Spurling Test)", aliases: "رادیکولوپاتی گردنی دیسک گردن", isCore: false, normalState: -1, detailHint: "تولید درد رادیکولار اندام فوقانی با اکستانسیون، چرخش به سمت درگیر و فشار محوری سر." },
  { id: "pe_trendelenburg", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Trendelenburg Sign", fa: "علامت ترندلنبرگ (Trendelenburg Sign)", aliases: "ضعف ابداکتورهای هیپ گلوتئوس مدیوس", isCore: false, normalState: -1, detailHint: "افتادگی لگن در سمت پای بلندشده هنگام ایستادن تک‌پا." },
  { id: "pe_faber", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "FABER (Patrick) Test", fa: "تست فابر / پاتریک (FABER Test)", aliases: "پاتولوژی مفصل هیپ یا ساکروایلیاک", isCore: false, normalState: -1, detailHint: "بروز درد کشاله ران (مفصل هیپ) یا ناحیه خلفی (مفصل ساکروایلیاک)." },
  { id: "pe_thomas", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Thomas Test", fa: "تست توماس (Thomas Test)", aliases: "کنتراکچر فلکسورهای هیپ ایلیوپسواس", isCore: false, normalState: -1, detailHint: "بلند شدن ران از روی تخت هنگام فلکسیون کامل ران سمت مقابل." },
  { id: "pe_bulge_sign", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Knee Bulge Sign", fa: "علامت بولج زانو (Bulge Sign)", aliases: "افیوژن خفیف زانو", isCore: false, normalState: -1, detailHint: "مشاهده موج مایع در سمت مدیال کشکک برای تشخیص افیوژن‌های کم‌حجم." },
  { id: "pe_patellar_tap", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Patellar Tap (Ballottement) Test", fa: "تست بالوتمنت کشکک (Patellar Tap Test)", aliases: "شناور شدن کشکک افیوژن زانو", isCore: false, normalState: -1, detailHint: "ضربه و برخورد کشکک به کندیل فمور در افیوژن‌های متوسط تا شدید زانو." },
  { id: "pe_adams_test", system: "musculoskeletal_spine", subGroup: "special_maneuvers", en: "Adams Forward Bend Test", fa: "تست خم شدن به جلو آدامز (Adams Forward Bend Test)", aliases: "غربالگری اسکولیوز برجستگی دنده‌ای", isCore: false, normalState: -1, detailHint: "مشاهده عدم تقارن یا قوز دنده‌ای (Rib Hump) هنگام خم شدن به جلو." },

  // ==========================================
  // 10. neurological (Core: 7)
  // ==========================================
  { id: "pe_neuro_gcs15", system: "neurological", subGroup: "consciousness_gcs", en: "Glasgow Coma Scale 15/15 (E4V5M6)", fa: "معیار کمای گلاسکو ۱۵/۱۵ (GCS 15)", aliases: "کاهش GCS سطح هوشیاری E4V5M6", isCore: true, normalState: 1, detailHint: "در صورت کاهش (منفی)، نمره دقیق اجزای چشمی (E)، کلامی (V) و حرکتی (M) را ثبت کنید." },
  { id: "pe_neuro_cn_intact", system: "neurological", subGroup: "cranial_nerves", en: "Cranial Nerves II–XII Grossly Intact", fa: "اعصاب کرانیال II تا XII سالم (CN II–XII Intact)", aliases: "اعصاب مغزی سالم", isCore: true, normalState: 1, detailHint: "در صورت نقص (منفی)، شماره عصب کرانیال و سمت درگیر را مشخص کنید." },
  { id: "pe_neuro_power5", system: "neurological", subGroup: "motor", en: "Motor Strength 5/5 Symmetric in All Extremities", fa: "قدرت عضلانی ۵/۵ و متقارن در چهار اندام (Motor 5/5)", aliases: "فورس عضلانی کامل ضعف عضلانی همی‌پارزی پاراپارزی", isCore: true, normalState: 1, detailHint: "در صورت ضعف (منفی)، اندام، گروه عضلانی و نمره MRC (از 0 تا 4) را ثبت کنید." },
  { id: "pe_neuro_sensation_intact", system: "neurological", subGroup: "sensory", en: "Sensation Intact to Light Touch and Pinprick", fa: "حس سطحی و عمقی سالم و متقارن (Sensation Intact)", aliases: "حس طبیعی هیپوستزی بی‌حسی پارستزی", isCore: true, normalState: 1, detailHint: "در صورت اختلال (منفی)، درماتوم یا قلمرو عصب محیطی درگیر را ثبت کنید." },
  { id: "pe_neuro_dtr_normal", system: "neurological", subGroup: "reflexes", en: "Deep Tendon Reflexes (DTRs) 2+ and Symmetric", fa: "رفلکس‌های تاندونی عمقی ۲+ و متقارن (DTRs 2+)", aliases: "رفلکس پاتلار آشیل بایسپس نرمال هایپررفلکسی هیپورفلکسی", isCore: true, normalState: 1, detailHint: "در صورت غیرطبیعی بودن (منفی)، کاهش (0/+1) یا افزایش (+3/+4) رفلکس را ثبت کنید." },
  { id: "pe_babinski", system: "neurological", subGroup: "reflexes", en: "Babinski Sign (Extensor Plantar Response)", fa: "علامت بابینسکی (Babinski Sign)", aliases: "رفلکس کف‌پایی فلکسور یا اکستانسور", isCore: true, normalState: -1, detailHint: "در حالت طبیعی (منفی) پاسخ کف‌پایی فلکسور (به سمت پایین) است؛ در صورت مثبت بودن (اکستانسور) سمت را مشخص کنید." },
  { id: "pe_nuchal_rigidity", system: "neurological", subGroup: "meningeal", en: "Nuchal Rigidity", fa: "سفتی گردن / مننژیسم (Nuchal Rigidity)", aliases: "تحریک مننژ مقاومت فلکسیون گردن مننژیت", isCore: true, normalState: -1, detailHint: "مقاومت غیرارادی در برابر فلکسیون غیرفعال گردن." },

  { id: "pe_neuro_cn1", system: "neurological", subGroup: "cranial_nerves", en: "CN I (Olfactory) Deficit", fa: "اختلال عصب I بویایی (CN I Deficit)", aliases: "آنوسمی هیپوسمی عصب بویایی", isCore: false, normalState: -1, detailHint: "کاهش یا فقدان حس بویایی." },
  { id: "pe_neuro_cn2", system: "neurological", subGroup: "cranial_nerves", en: "CN II (Optic) Visual Field or Acuity Deficit", fa: "نقص میدان یا حدت بینایی عصب II (CN II Deficit)", aliases: "همی‌آپنوپی اسکوتوم کاهش دید", isCore: false, normalState: -1, detailHint: "نوع نقص میدان بینایی در تست Confrontation یا کاهش حدت بینایی." },
  { id: "pe_neuro_cn3", system: "neurological", subGroup: "cranial_nerves", en: "CN III (Oculomotor) Palsy", fa: "فلج عصب III اوکولوموتور (CN III Palsy)", aliases: "پتوز میدریاز انحراف چشم به پایین و خارج", isCore: false, normalState: -1, detailHint: "سمت، وضعیت مردمک (درگیر یا حفظ‌شده) و پتوز." },
  { id: "pe_neuro_cn4", system: "neurological", subGroup: "cranial_nerves", en: "CN IV (Trochlear) Palsy", fa: "فلج عصب IV تروکلئار (CN IV Palsy)", aliases: "فلج عضله مایل فوقانی دوبینی عمودی", isCore: false, normalState: -1, detailHint: "اختلال نگاه به پایین و داخل و تیلت جبرانی سر." },
  { id: "pe_neuro_cn5", system: "neurological", subGroup: "cranial_nerves", en: "CN V (Trigeminal) Sensory or Motor Deficit", fa: "نقص حسی یا حرکتی عصب V سه‌قلو (CN V Deficit)", aliases: "حس صورت V1 V2 V3 رفلکس قرنیه عضلات جونده", isCore: false, normalState: -1, detailHint: "شاخه درگیر (V1, V2, V3)، سمت و وضعیت رفلکس قرنیه." },
  { id: "pe_neuro_cn6", system: "neurological", subGroup: "cranial_nerves", en: "CN VI (Abducens) Palsy", fa: "فلج عصب VI ابدوسنس (CN VI Palsy)", aliases: "اختلال ابداکشن چشم رکتوس خارجی", isCore: false, normalState: -1, detailHint: "محدودیت حرکت چشم به خارج و سمت درگیر." },
  { id: "pe_neuro_cn7", system: "neurological", subGroup: "cranial_nerves", en: "CN VII (Facial) Palsy", fa: "فلج عصب VII فاسیال (CN VII Facial Palsy)", aliases: "فلج بل عدم تقارن صورت افتادگی گوشه لب", isCore: false, normalState: -1, detailHint: "مرکزی (حفظ پیشانی) یا محیطی (درگیری کل نیمه صورت) بودن و سمت." },
  { id: "pe_neuro_cn8", system: "neurological", subGroup: "cranial_nerves", en: "CN VIII (Vestibulocochlear) Deficit", fa: "نقص عصب VIII دهلیزی‌ـ‌حلزونی (CN VIII Deficit)", aliases: "کاهش شنوایی اختلال وستیبولار", isCore: false, normalState: -1, detailHint: "کاهش شنوایی در تست نجوا یا یافته‌های وستیبولار." },
  { id: "pe_neuro_cn9_10", system: "neurological", subGroup: "cranial_nerves", en: "CN IX / X (Glossopharyngeal / Vagus) Deficit", fa: "نقص اعصاب IX و X / اختلال کام و رفلکس گگ (CN IX & X Deficit)", aliases: "رفلکس گگ دیسفاژی خشونت صدا انحراف کام", isCore: false, normalState: -1, detailHint: "عدم تقارن بالا رفتن کام نرم، انحراف اوولا یا کاهش رفلکس گگ." },
  { id: "pe_neuro_cn11", system: "neurological", subGroup: "cranial_nerves", en: "CN XI (Accessory) Weakness", fa: "ضعف عصب XI فرعی (CN XI Weakness)", aliases: "ضعف عضله تراپزیوس و استرنوکلئیدوماستوئید", isCore: false, normalState: -1, detailHint: "ضعف بالا انداختن شانه یا چرخش سر در برابر مقاومت." },
  { id: "pe_neuro_cn12", system: "neurological", subGroup: "cranial_nerves", en: "CN XII (Hypoglossal) Palsy", fa: "فلج عصب XII زیرزبانی (CN XII Palsy)", aliases: "انحراف زبان آتروفی یا فاسیکولاسیون زبان", isCore: false, normalState: -1, detailHint: "سمت انحراف زبان هنگام بیرون آوردن." },
  { id: "pe_neuro_weakness", system: "neurological", subGroup: "motor", en: "Focal Motor Weakness or Pronator Drift", fa: "ضعف حرکتی فوکال یا پروناتور دریفت (Focal Weakness / Drift)", aliases: "پروناتور دریفت همی‌پارزی پلژی", isCore: false, normalState: -1, detailHint: "توزیع ضعف (همی‌پارزی، پاراپارزی، پروگزیمال/دیستال) و سمت." },
  { id: "pe_neuro_atrophy", system: "neurological", subGroup: "motor", en: "Muscle Atrophy or Fasciculations", fa: "آتروفی یا فاسیکولاسیون عضلانی (Atrophy / Fasciculations)", aliases: "تحلیل عضله پرش عضلانی", isCore: false, normalState: -1, detailHint: "گروه عضلانی درگیر و سمت." },
  { id: "pe_neuro_spasticity", system: "neurological", subGroup: "motor", en: "Spasticity (Hypertonia)", fa: "اسپاستیسیتی / افزایش تون عضلانی (Spasticity)", aliases: "افزایش تون چاقوی ضامن‌دار UMN", isCore: false, normalState: -1, detailHint: "افزایش تون وابسته به سرعت حرکت در اندام درگیر." },
  { id: "pe_neuro_rigidity", system: "neurological", subGroup: "motor", en: "Lead-Pipe or Cogwheel Rigidity", fa: "ریجیدیتی لوله سربی یا چرخ‌دنده‌ای (Rigidity)", aliases: "سفتی عضلانی پارکینسون", isCore: false, normalState: -1, detailHint: "نوع ریجیدیتی و اندام درگیر." },
  { id: "pe_neuro_flaccidity", system: "neurological", subGroup: "motor", en: "Hypotonia / Flaccidity", fa: "هیپوتونی / شلی عضلانی (Flaccidity)", aliases: "کاهش تون عضلانی LMN", isCore: false, normalState: -1, detailHint: "اندام و سمت دارای کاهش تون." },
  { id: "pe_neuro_sensory_level", system: "neurological", subGroup: "sensory", en: "Spinal Sensory Level", fa: "سطح حسی نخاعی (Dermatomal Sensory Level)", aliases: "سطح حسی ضایعه نخاعی", isCore: false, normalState: -1, detailHint: "سطح دقیق درماتومی تغییر حس (مثلاً T4 یا T10)." },
  { id: "pe_neuro_vibration_impaired", system: "neurological", subGroup: "sensory", en: "Impaired Vibration or Proprioception", fa: "اختلال حس ارتعاش یا حس وضعیت مفصل (Impaired Vibration / Proprioception)", aliases: "کاهش حس عمقی نوروپاتی محیطی ستون خلفی", isCore: false, normalState: -1, detailHint: "بررسی با دیاپازون ۱۲۸ هرتز و حس وضعیت شست پا." },
  { id: "pe_neuro_hyperreflexia", system: "neurological", subGroup: "reflexes", en: "Hyperreflexia (3+ or 4+)", fa: "هایپررفلکسی (Hyperreflexia)", aliases: "افزایش رفلکس تاندونی", isCore: false, normalState: -1, detailHint: "تاندون و سمت دارای افزایش رفلکس." },
  { id: "pe_neuro_hyporeflexia", system: "neurological", subGroup: "reflexes", en: "Hyporeflexia or Areflexia (0 or 1+)", fa: "هیپورفلکسی یا آرفلکسی (Hyporeflexia / Areflexia)", aliases: "کاهش یا غیاب رفلکس تاندونی", isCore: false, normalState: -1, detailHint: "تاندون و سمت دارای کاهش یا فقدان رفلکس." },
  { id: "pe_neuro_clonus", system: "neurological", subGroup: "reflexes", en: "Ankle Clonus", fa: "کلونوس مچ پا (Clonus)", aliases: "کلونوس پایدار", isCore: false, normalState: -1, detailHint: "تعداد ضربات و پایدار (Sustained) بودن کلونوس." },
  { id: "pe_hoffmann", system: "neurological", subGroup: "reflexes", en: "Hoffmann Sign", fa: "علامت هوفمن (Hoffmann Sign)", aliases: "رفلکس پاتولوژیک اندام فوقانی میلوپاتی گردنی", isCore: false, normalState: -1, detailHint: "فلکسیون غیرارادی شست و انگشت اشاره پس از ضربه به ناخن انگشت میانی." },
  { id: "pe_neuro_finger_nose", system: "neurological", subGroup: "cerebellar", en: "Dysmetria on Finger-to-Nose Test", fa: "دیس‌متری در تست انگشت به بینی (Finger-to-Nose Dysmetria)", aliases: "تست انگشت به بینی مخچه لرزش قصدی", isCore: false, normalState: -1, detailHint: "در حالت طبیعی (منفی) تست دقیق و بدون خطاست؛ در صورت دیس‌متری (مثبت) سمت را ثبت کنید." },
  { id: "pe_neuro_dysdiadochokinesia", system: "neurological", subGroup: "cerebellar", en: "Dysdiadochokinesia", fa: "دیس‌دیادوکوکینزی / اختلال حرکات متناوب سریع (Dysdiadochokinesia)", aliases: "حرکات متناوب سریع دست مخچه", isCore: false, normalState: -1, detailHint: "کندی و ناهماهنگی در چرخش سریع و متناوب کف و پشت دست." },
  { id: "pe_neuro_heel_shin", system: "neurological", subGroup: "cerebellar", en: "Abnormal Heel-to-Shin Test", fa: "اختلال تست پاشنه به ساق (Abnormal Heel-to-Shin)", aliases: "تست پاشنه به زانو و ساق مخچه", isCore: false, normalState: -1, detailHint: "انحراف پاشنه پا از روی تیغه قدامی تیبیا و سمت درگیر." },
  { id: "pe_romberg", system: "neurological", subGroup: "cerebellar", en: "Romberg Sign", fa: "تست رومبرگ (Romberg Test)", aliases: "عدم تعادل با بستن چشم آتاکسی حسی", isCore: false, normalState: -1, detailHint: "در حالت طبیعی (منفی) تعادل با بستن چشم حفظ می‌شود؛ از دست دادن تعادل با بستن چشم نشانه رومبرگ مثبت است." },
  { id: "pe_neuro_tandem_gait", system: "neurological", subGroup: "cerebellar", en: "Impaired Tandem (Heel-to-Toe) Gait", fa: "اختلال راه‌رفتن پاشنه به پنجه (Impaired Tandem Gait)", aliases: "تندم گیت آتاکسی مخچه‌ای", isCore: false, normalState: -1, detailHint: "عدم توانایی راه رفتن روی خط مستقیم به صورت پاشنه به پنجه." },
  { id: "pe_kernig", system: "neurological", subGroup: "meningeal", en: "Kernig Sign", fa: "علامت کرنیگ (Kernig Sign)", aliases: "درد و مقاومت اکستانسیون زانو مننژیت", isCore: false, normalState: -1, detailHint: "مقاومت و درد همسترینگ هنگام اکستانسیون زانو در حالی که ران ۹۰ درجه خم شده است." },
  { id: "pe_brudzinski", system: "neurological", subGroup: "meningeal", en: "Brudzinski Sign", fa: "علامت برودزینسکی (Brudzinski Sign)", aliases: "فلکسیون غیرارادی زانو و ران با خم کردن گردن", isCore: false, normalState: -1, detailHint: "فلکسیون غیرارادی مفصل ران و زانو در پاسخ به فلکسیون غیرفعال گردن." },

  // ==========================================
  // 11. surgical_wound_drain_stoma (Core: 6)
  // ==========================================
  { id: "pe_wound_cdi", system: "surgical_wound_drain_stoma", subGroup: "incision_wound", en: "Clean, Dry, and Intact Incision (CDI)", fa: "برش جراحی تمیز، خشک و سالم (CDI)", aliases: "زخم جراحی سالم لبه‌های زخم بسته", isCore: true, normalState: 1, detailHint: "لبه‌های برش به خوبی به هم رسیده و فاقد شواهد عفونت است." },
  { id: "pe_wound_erythema", system: "surgical_wound_drain_stoma", subGroup: "incision_wound", en: "Incisional Erythema, Warmth, or Induration", fa: "اریتم، گرمی یا سفتی اطراف برش جراحی (Wound Erythema)", aliases: "قرمزی و التهاب زخم سلولیت محل عمل", isCore: true, normalState: -1, detailHint: "گسترش اریتم از لبه زخم به سانتی‌متر و وجود سفتی یا تندرنس." },
  { id: "pe_wound_purulent_drainage", system: "surgical_wound_drain_stoma", subGroup: "wound_complications", en: "Purulent or Abnormal Wound Drainage", fa: "ترشح چرکی یا غیرطبیعی از زخم (Wound Drainage)", aliases: "عفونت محل جراحی SSI چرک زخم", isCore: true, normalState: -1, detailHint: "نوع ترشح (چرکی، سروسانگوینوس، سروزی)، رنگ، بو و حجم." },
  { id: "pe_wound_dehiscence", system: "surgical_wound_drain_stoma", subGroup: "incision_wound", en: "Wound Dehiscence", fa: "دهیسنس / بازشدگی لبه‌های زخم (Wound Dehiscence)", aliases: "باز شدن بخیه و فاشیا", isCore: true, normalState: -1, detailHint: "طول و عمق بازشدگی و وضعیت سلامت فاشیای عمقی." },
  { id: "pe_wound_dressing_clean", system: "surgical_wound_drain_stoma", subGroup: "dressing", en: "Clean, Dry, and Intact Dressing", fa: "پانسمان تمیز و خشک (Clean & Dry Dressing)", aliases: "پانسمان اشباع یا خیس شده", isCore: true, normalState: 1, detailHint: "در صورت اشباع شدن پانسمان (منفی)، مقدار و ماهیت ترشح را ثبت کنید." },
  { id: "pe_drain_patent", system: "surgical_wound_drain_stoma", subGroup: "drains", en: "Surgical Drain Patent & Functioning", fa: "درن جراحی باز و دارای عملکرد مناسب (Drain Patent)", aliases: "درن هموواک جکسون پرات چست تیوب", isCore: true, normalState: 0, detailHint: "نوع درن، حجم ۲۴ ساعته و رنگ خروجی (سروزی، هموراژیک، صفراوی) را ثبت کنید." },

  { id: "pe_wound_sutures_intact", system: "surgical_wound_drain_stoma", subGroup: "incision_wound", en: "Sutures or Staples Intact", fa: "بخیه‌ها یا استپل‌ها سالم و برقرار (Sutures / Staples Intact)", aliases: "بخیه سالم یا باز شده", isCore: false, normalState: 0, detailHint: "وضعیت بخیه‌ها یا استپل‌های پوستی." },
  { id: "pe_wound_evisceration", system: "surgical_wound_drain_stoma", subGroup: "incision_wound", en: "Wound Evisceration", fa: "اویسراسیون / خروج احشاء از زخم (Evisceration)", aliases: "بیرون زدگی روده از برش جراحی", isCore: false, normalState: -1, detailHint: "اورژانس جراحی؛ پوشش با گاز استریل مرطوب به نرمال سالین." },
  { id: "pe_wound_seroma", system: "surgical_wound_drain_stoma", subGroup: "wound_complications", en: "Postoperative Seroma or Hematoma", fa: "سروما یا هماتوم محل جراحی (Seroma / Hematoma)", aliases: "تجمع مایع یا خون زیر زخم فلکتوانس", isCore: false, normalState: -1, detailHint: "ابعاد تجمع، قوام، تموج (Fluctuance) و تغییر رنگ پوست." },
  { id: "pe_wound_necrosis", system: "surgical_wound_drain_stoma", subGroup: "wound_complications", en: "Wound Edge Necrosis or Eschar", fa: "نکروز لبه زخم یا اسکار نکروتیک (Wound Necrosis)", aliases: "سیاه شدن لبه زخم بافت نکروتیک", isCore: false, normalState: -1, detailHint: "وسعت بافت غیرزنده و وضعیت خون‌رسانی لبه‌ها." },
  { id: "pe_drain_obstructed", system: "surgical_wound_drain_stoma", subGroup: "drains", en: "Drain Obstruction or Dislodgement", fa: "انسداد، نشت یا جابجایی درن (Drain Complication)", aliases: "قطع خروجی درن خارج شدن درن", isCore: false, normalState: -1, detailHint: "بررسی مسیر لوله، لخته، از دست رفتن خلاء یا التهاب محل خروج." },
  { id: "pe_stoma_viable", system: "surgical_wound_drain_stoma", subGroup: "stoma", en: "Viable Pink, Moist Stoma", fa: "استومای زنده، صورتی و مرطوب (Viable Stoma)", aliases: "ایلئوستومی کلستومی سالم", isCore: false, normalState: 0, detailHint: "رنگ صورتی/قرمز، رطوبت مخاط و حجم و قوام خروجی کیسه." },
  { id: "pe_stoma_ischemic", system: "surgical_wound_drain_stoma", subGroup: "stoma", en: "Dusky, Pale, or Necrotic Stoma", fa: "ایسکمی یا نکروز استوما (Dusky / Necrotic Stoma)", aliases: "استومای تیره کبود یا سیاه", isCore: false, normalState: -1, detailHint: "تغییر رنگ به بنفش تیره یا سیاه و سطح گسترش نسبت به فاشیا." },
  { id: "pe_stoma_retraction", system: "surgical_wound_drain_stoma", subGroup: "stoma", en: "Stoma Retraction, Prolapse, or Parastomal Hernia", fa: "رتراکشن، پرولاپس یا فتق پارااستومال (Stoma Complication)", aliases: "فرورفتگی یا بیرون‌زدگی استوما فتق دور استوما", isCore: false, normalState: -1, detailHint: "نوع عارضه مکانیکی استوما و وضعیت پوست پری‌استومال." },
  { id: "pe_stoma_dermatitis", system: "surgical_wound_drain_stoma", subGroup: "stoma", en: "Peristomal Skin Dermatitis or Excoriation", fa: "درماتیت و سوختگی پوست اطراف استوما (Peristomal Dermatitis)", aliases: "التهاب پوست دور استوما نشت کیسه", isCore: false, normalState: -1, detailHint: "وسعت اریتم و اروزیون پوست اطراف استوما." },

  // ==========================================
  // 12. trauma_atls_signs (Core: 6)
  // ==========================================
  { id: "pe_trauma_distal_nv_intact", system: "trauma_atls_signs", subGroup: "extremities", en: "Distal Neurovascular Status Intact", fa: "وضعیت عروقی‌ـ‌عصبی دیستال اندام‌ها سالم (Distal NV Intact)", aliases: "نبض حس و حرکت دیستال در تروما سندرم کمپارتمان", isCore: true, normalState: 1, detailHint: "در صورت اختلال (منفی)، اندام، وضعیت نبض، رنگ، دما، حس و حرکت را ثبت کنید." },
  { id: "pe_trauma_subcutaneous_emphysema", system: "trauma_atls_signs", subGroup: "chest", en: "Subcutaneous Emphysema", fa: "آمفیزم زیرجلدی (Subcutaneous Emphysema)", aliases: "کریپتاسیون هوا زیر پوست گردن یا قفسه سینه", isCore: true, normalState: -1, detailHint: "محل و وسعت کریپتاسیون زیرجلدی." },
  { id: "pe_trauma_seatbelt", system: "trauma_atls_signs", subGroup: "abdomen_pelvis", en: "Seatbelt Sign", fa: "علامت کمربند ایمنی (Seatbelt Sign)", aliases: "اکیموز خطی کمربند ایمنی روی شکم یا سینه", isCore: true, normalState: -1, detailHint: "مسیر کبودی یا سایش کمربند (گردن، قفسه سینه، شکم)." },
  { id: "pe_trauma_pelvic_instability", system: "trauma_atls_signs", subGroup: "abdomen_pelvis", en: "Pelvic Ring Instability or Tenderness", fa: "ناپایداری یا تندرنس حلقه لگنی (Pelvic Instability)", aliases: "شکستگی لگن در تروما", isCore: true, normalState: -1, detailHint: "فقط یک‌بار مانور ملایم فشاری انجام شود؛ از تکرار مانور خودداری کنید." },
  { id: "pe_trauma_limb_deformity", system: "trauma_atls_signs", subGroup: "extremities", en: "Acute Limb Deformity, Crepitus, or Open Fracture", fa: "دفورمیتی حاد، کریپتوس یا شکستگی باز اندام (Fracture / Deformity)", aliases: "بدشکلی اندام شکستگی استخوان بلند", isCore: true, normalState: -1, detailHint: "استخوان/اندام درگیر، باز یا بسته بودن و وضعیت زخم." },
  { id: "pe_trauma_battle", system: "trauma_atls_signs", subGroup: "head_face", en: "Basilar Skull Fracture Signs (Battle Sign / Raccoon Eyes)", fa: "علائم شکستگی قاعده جمجمه: علامت بتل یا چشم راکونی (Basilar Skull Signs)", aliases: "اکیموز ماستوئید پشت گوش کبودی دور چشم", isCore: true, normalState: -1, detailHint: "وجود علامت بتل (اکیموز ماستوئید) یا چشم راکونی (اکیموز پری‌اوربیتال)." },

  { id: "pe_trauma_hemotympanum", system: "trauma_atls_signs", subGroup: "head_face", en: "Hemotympanum", fa: "هموتیمپانوم / خون پشت پرده صماخ (Hemotympanum)", aliases: "کبودی پرده گوش در تروما", isCore: false, normalState: -1, detailHint: "سمت درگیر در اتوسکوپی." },
  { id: "pe_trauma_csf_rhinorrhea", system: "trauma_atls_signs", subGroup: "head_face", en: "Suspected CSF Rhinorrhea or Otorrhea", fa: "رینوره یا اوتوره مشکوک به مایع مغزی‌ـ‌نخاعی (CSF Leak)", aliases: "ترشح شفاف از بینی یا گوش علامت هاله Halo sign", isCore: false, normalState: -1, detailHint: "محل نشت (بینی یا گوش) و وجود علامت Halo." },
  { id: "pe_trauma_skull_step_off", system: "trauma_atls_signs", subGroup: "head_face", en: "Palpable Skull Depression or Facial Instability", fa: "فرورفتگی جمجمه یا ناپایداری استخوان‌های صورت (Skull / Midface Instability)", aliases: "شکستگی جمجمه شکستگی لوفور و فک", isCore: false, normalState: -1, detailHint: "محل استپ‌آف جمجمه، ناپایداری میدفیس (LeFort) یا مال‌اکلوژن فک." },
  { id: "pe_trauma_flail_chest", system: "trauma_atls_signs", subGroup: "chest", en: "Flail Chest Segment", fa: "قفسه سینه شناور (Flail Chest)", aliases: "شکستگی چند دنده حرکت پارادوکسیک سینه", isCore: false, normalState: -1, detailHint: "سمت و ناحیه دارای حرکت پارادوکسیک دیواره قفسه سینه." },
  { id: "pe_trauma_open_chest_wound", system: "trauma_atls_signs", subGroup: "chest", en: "Open / Sucking Chest Wound", fa: "زخم باز یا مکنده قفسه سینه (Open Pneumothorax Wound)", aliases: "پنوموتوراکس باز زخم نافذ توراکس", isCore: false, normalState: -1, detailHint: "محل زخم نافذ و تعبیه پانسمان سه‌طرفه." },
  { id: "pe_trauma_perineal_ecchymosis", system: "trauma_atls_signs", subGroup: "abdomen_pelvis", en: "Perineal / Scrotal Hematoma or Blood at Meatus", fa: "هماتوم پرینه/اسکروتوم یا خون در مئاتوس ادراری (Urethral Injury Signs)", aliases: "خون در نوک مجرای ادرار آسیب مجرا هماتوم پروانه‌ای", isCore: false, normalState: -1, detailHint: "هشدار آسیب مجرای ادرار؛ کنتراندیکاسیون سوندگذاری کور." },
  { id: "pe_trauma_high_riding_prostate", system: "trauma_atls_signs", subGroup: "abdomen_pelvis", en: "High-Riding or Non-Palpable Prostate in Trauma", fa: "پروستات جابجاشده/بالا در تروما (High-Riding Prostate)", aliases: "پروستات بالا در DRE ترومای لگن", isCore: false, normalState: -1, detailHint: "یافته مطرح‌کننده آسیب مجرای خلفی در ترومای لگن." }
